const KEY='adria-maja-consent-v1';
export const CONSENT_MAX_AGE=180*24*60*60*1000;
const words={
 hr:{title:'Vaše postavke privatnosti',text:'Nužna pohrana pamti vaše postavke i omogućuje rad stranice. Google karte uključuju se samo uz vaše dopuštenje. Ne koristimo analitičke ni marketinške kolačiće.',necessary:'Samo nužno',all:'Prihvati sve',settings:'Postavke kolačića',save:'Spremi postavke',close:'Zatvori',essential:'Nužno · uvijek uključeno',essentialText:'Postavke jezika, veličine teksta, privatnosti i administratorska prijava.',external:'Vanjske usluge · Google karte',externalText:'Učitavanje Google karata povezuje vaš preglednik s Googleom, koji može pohraniti kolačiće i primiti tehničke podatke o posjetu.',map:'Google karta nije učitana',mapText:'Za prikaz karte dopustite vanjske usluge u postavkama kolačića.',privacy:'Privatnost'},
 en:{title:'Your privacy preferences',text:'Necessary storage remembers your preferences and keeps the website working. Google Maps loads only with your permission. We do not use analytics or marketing cookies.',necessary:'Necessary only',all:'Accept all',settings:'Cookie settings',save:'Save preferences',close:'Close',essential:'Necessary · always enabled',essentialText:'Language, text size, privacy preferences and administrator sign-in.',external:'External services · Google Maps',externalText:'Loading Google Maps connects your browser to Google, which may store cookies and receive technical information about your visit.',map:'Google Maps has not loaded',mapText:'To display the map, allow external services in cookie settings.',privacy:'Privacy'},
 de:{title:'Ihre Datenschutzeinstellungen',text:'Notwendiger Speicher merkt sich Ihre Einstellungen und ermöglicht den Betrieb der Website. Google Maps wird nur mit Ihrer Zustimmung geladen. Wir verwenden keine Analyse- oder Marketing-Cookies.',necessary:'Nur notwendige',all:'Alle akzeptieren',settings:'Cookie-Einstellungen',save:'Einstellungen speichern',close:'Schließen',essential:'Notwendig · immer aktiviert',essentialText:'Sprache, Textgröße, Datenschutzeinstellungen und Administrator-Anmeldung.',external:'Externe Dienste · Google Maps',externalText:'Beim Laden von Google Maps verbindet sich Ihr Browser mit Google. Google kann Cookies speichern und technische Informationen über Ihren Besuch erhalten.',map:'Google Maps wurde nicht geladen',mapText:'Erlauben Sie externe Dienste in den Cookie-Einstellungen, um die Karte anzuzeigen.',privacy:'Datenschutz'},
 cs:{title:'Vaše nastavení soukromí',text:'Nezbytné úložiště si pamatuje vaše nastavení a zajišťuje chod webu. Mapy Google se načtou pouze s vaším svolením. Nepoužíváme analytické ani marketingové cookies.',necessary:'Pouze nezbytné',all:'Přijmout vše',settings:'Nastavení cookies',save:'Uložit nastavení',close:'Zavřít',essential:'Nezbytné · vždy zapnuté',essentialText:'Jazyk, velikost textu, nastavení soukromí a přihlášení správce.',external:'Externí služby · Mapy Google',externalText:'Načtení Map Google propojí váš prohlížeč se společností Google, která může ukládat cookies a získat technické informace o návštěvě.',map:'Mapy Google nejsou načteny',mapText:'Pro zobrazení mapy povolte externí služby v nastavení cookies.',privacy:'Soukromí'}
};
const copy=language=>words[language]||words.hr;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function parseConsent(raw,now=Date.now()){try{const value=typeof raw==='string'?JSON.parse(raw):raw;if(value?.version!==1||typeof value.external!=='boolean'||!Number.isFinite(value.savedAt)||value.savedAt>now||now-value.savedAt>=CONSENT_MAX_AGE)return null;return {version:1,external:value.external,savedAt:value.savedAt}}catch{return null}}
function placeholder(language){const c=copy(language);return `<div class="consent-map-message"><strong>${esc(c.map)}</strong><p>${esc(c.mapText)}</p><button type="button" class="btn outline" data-consent-open>${esc(c.settings)}</button></div>`}
export function consentMapMarkup(src,title,language='hr'){return `<div class="consent-map" data-consent-map="${esc(src)}" data-map-title="${esc(title)}">${placeholder(language)}</div>`}
export function createConsent({getLang=()=> 'hr'}={}){
 let value=null,opener=null;
 try{value=parseConsent(localStorage.getItem(KEY))}catch{}
 function applyMaps(){document.querySelectorAll('[data-consent-map]').forEach(box=>{if(value?.external){if(box.querySelector('iframe'))return;const frame=document.createElement('iframe');frame.src=box.dataset.consentMap;frame.title=box.dataset.mapTitle;frame.loading='lazy';frame.referrerPolicy='no-referrer-when-downgrade';frame.allowFullscreen=true;box.replaceChildren(frame)}else if(box.querySelector('iframe'))box.innerHTML=placeholder(getLang())})}
 function save(external){value={version:1,external,savedAt:Date.now()};try{localStorage.setItem(KEY,JSON.stringify(value))}catch{}document.querySelector('#consent-dialog')?.close();sync();opener?.focus()}
 function open(target){opener=target;const dialog=document.querySelector('#consent-dialog');dialog.querySelector('#consent-external').checked=value?.external===true;dialog.showModal()}
 function sync(){
  if(value&&!parseConsent(value))value=null;
  const c=copy(getLang());let root=document.querySelector('#consent-root');if(!root){root=document.createElement('div');root.id='consent-root';document.body.append(root)}
  root.innerHTML=`${value?'':`<section class="consent-banner" aria-label="${esc(c.settings)}"><h2>${esc(c.title)}</h2><p>${esc(c.text)} <a href="/privatnost/${getLang()==='hr'?'':'?lang='+getLang()}">${esc(c.privacy)}</a></p><div class="consent-actions"><button type="button" class="btn outline" data-consent-necessary>${esc(c.necessary)}</button><button type="button" class="btn outline" data-consent-open>${esc(c.settings)}</button><button type="button" class="btn" data-consent-all>${esc(c.all)}</button></div></section>`}<dialog id="consent-dialog" class="consent-dialog" aria-labelledby="consent-title"><div class="consent-dialog-top"><h2 id="consent-title">${esc(c.settings)}</h2><button type="button" class="consent-close" aria-label="${esc(c.close)}">×</button></div><p>${esc(c.text)}</p><div class="consent-option"><strong>${esc(c.essential)}</strong><p>${esc(c.essentialText)}</p></div><label class="consent-option"><span><input id="consent-external" type="checkbox" ${value?.external?'checked':''}> ${esc(c.external)}</span><p>${esc(c.externalText)}</p></label><div class="consent-actions"><button type="button" class="btn outline" data-consent-necessary>${esc(c.necessary)}</button><button type="button" class="btn" data-consent-save>${esc(c.save)}</button></div></dialog>`;
  root.querySelector('.consent-close').onclick=()=>{root.querySelector('dialog').close();opener?.focus()};applyMaps();
 }
 document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.hasAttribute('data-consent-open'))open(target);if(target.hasAttribute('data-consent-necessary'))save(false);if(target.hasAttribute('data-consent-all'))save(true);if(target.hasAttribute('data-consent-save'))save(document.querySelector('#consent-external').checked)});
 window.addEventListener('storage',event=>{if(event.key===KEY){value=parseConsent(event.newValue);sync()}});
 return {sync};
}
